{
  "name": "超导持久磁体线圈",
  "name_en": "Persistent superconducting magnet coil",
  "manufacturer": "",
  "description": "这是一种带持久开关与加热器的超导磁体线圈，用于低温与量子器件实验中产生稳定磁场。实验时通常先由外部电流源给线圈充电，再切换到持久模式以在断开电源后维持磁场，并可进行失超检查、电流与磁场换算以及磁场缓慢扫场控制。",
  "description_en": "This is a superconducting magnet coil with a persistent switch and heater, used in cryogenic and quantum-device experiments to generate stable magnetic fields. The coil is typically energized by an external current source and then switched into persistent mode so the field can be maintained after disconnecting the source. It supports quench checking, current-field conversion, and controlled field ramping.",
  "actions": [
    {
      "action_name": "auto-get_all",
      "description": "获取磁体线圈的整体状态信息。",
      "description_en": "Get the overall status information of the magnet coil."
    },
    {
      "action_name": "auto-check_for_quench",
      "description": "检查线圈是否发生失超。",
      "description_en": "Check whether the coil is in a quench condition."
    },
    {
      "action_name": "auto-get_source_current",
      "description": "获取外部电流源对线圈提供的电流。",
      "description_en": "Get the current supplied to the coil by the external current source."
    },
    {
      "action_name": "auto-set_source_current",
      "description": "设置外部电流源对线圈提供的电流。",
      "description_en": "Set the current supplied to the coil by the external current source."
    },
    {
      "action_name": "auto-get_heater_current",
      "description": "获取持久开关加热器电流。",
      "description_en": "Get the persistent-switch heater current."
    },
    {
      "action_name": "auto-set_heater_current",
      "description": "设置持久开关加热器电流。",
      "description_en": "Set the persistent-switch heater current."
    },
    {
      "action_name": "auto-get_switch_state",
      "description": "获取持久开关状态。",
      "description_en": "Get the persistent-switch state."
    },
    {
      "action_name": "auto-set_switch_state",
      "description": "设置持久开关状态，使线圈在持久模式与常导供电模式之间切换。",
      "description_en": "Set the persistent-switch state to switch the coil between persistent mode and externally powered normal-conducting mode."
    },
    {
      "action_name": "auto-set_field",
      "description": "设置目标磁场。",
      "description_en": "Set the target magnetic field."
    },
    {
      "action_name": "auto-get_field",
      "description": "获取当前保存或记录的磁场值。",
      "description_en": "Get the current stored or recorded magnetic field value."
    },
    {
      "action_name": "auto-measure_field",
      "description": "测量线圈产生的磁场。",
      "description_en": "Measure the magnetic field produced by the coil."
    },
    {
      "action_name": "auto-step_field_to_value",
      "description": "将磁场逐步扫到指定值。",
      "description_en": "Ramp the magnetic field step by step to a specified value."
    },
    {
      "action_name": "auto-field_to_curr",
      "description": "将目标磁场换算为所需线圈电流。",
      "description_en": "Convert a target magnetic field to the required coil current."
    },
    {
      "action_name": "auto-curr_to_field",
      "description": "将线圈电流换算为对应磁场。",
      "description_en": "Convert coil current to the corresponding magnetic field."
    },
    {
      "action_name": "auto-fake_folder",
      "description": "创建一个用于磁体测量记录的占位数据文件夹。",
      "description_en": "Create a placeholder data folder for magnet measurement records."
    },
    {
      "action_name": "auto-compensate_for_drift",
      "description": "在线圈处于持久状态时补偿磁场漂移，或将源电流降至零以便断开电流源。",
      "description_en": "Compensate field drift while the coil is in persistent mode, or ramp the source current to zero for source disconnection."
    },
    {
      "action_name": "auto-bring_source_to_field",
      "description": "使外部电流源电流与当前持久磁场对应，便于后续切换开关或继续控场。",
      "description_en": "Bring the external source current into agreement with the present persistent field for subsequent switch operation or further field control."
    }
  ],
  "tag_hints": [
    "superconducting magnet",
    "persistent switch",
    "magnetic field control",
    "quench detection",
    "current ramping",
    "cryogenic experiments",
    "quantum device measurement"
  ]
}

